operty_ownership_document","condition":"always"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":null,"maxJod":null,"note":{"en":"0.5% of the annual rent (max 15 JOD) + 0.3% of the total contract value in stamps","ar":"0.5% من الإيجار السنوي (بحد أقصى 15 ديناراً) + 0.003 من قيمة العقد الكلية طوابع"},"verified":"yes"},"days":{"value":0,"note":{"en":"Online, same day","ar":"إلكترونياً في نفس اليوم"},"verified":"yes"},"condition":"if_rented","notes":{"en":"Only if you rent the premises.","ar":"فقط إذا كان الموقع مستأجراً."},"sourceIds":["S10"],"key":"gam_rental_certificate","legalForm":"llc"},{"order":4,"id":"vocational_license","title":{"en":"Get the vocational licence for your shop or office","ar":"الحصول على رخصة المهن للمحل أو المكتب"},"officeId":"GAM","requiredDocs":[{"docId":"registration_certificate","condition":"always"},{"docId":"chamber_certificate","condition":"always"},{"docId":"gam_rental_certificate","condition":"if_rented"},{"docId":"property_ownership_document","condition":"always"},{"docId":"building_documents","condition":"always"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":3,"maxJod":1000,"note":{"en":"Depends on the activity: fixed-fee activities 25-200 JOD for individual traders (3-1,000 JOD for companies); capital-based activities 40-750 JOD. Plus 15 JOD per m² of signboard (min 1 m²) and an extra 20% of the licence fee (min 20 JOD).","ar":"حسب النشاط: الأنشطة ذات الرسم الثابت 25 إلى 200 دينار للتاجر الفرد (3 إلى 1,000 دينار للشركات)؛ والأنشطة حسب رأس المال 40 إلى 750 ديناراً. إضافة إلى 15 ديناراً لكل متر مربع من اللوحة الإعلانية (بحد أدنى متر واحد) و20% من رسم الرخصة (بحد أدنى 20 ديناراً)."},"verified":"yes"},"days":{"value":0,"note":{"en":"Online, same day once the documents are complete","ar":"إلكترونياً في نفس اليوم بعد اكتمال الوثائق"},"verified":"yes"},"condition":"always","notes":{"en":"Some activities need prior approval from a sector authority.","ar":"تحتاج بعض الأنشطة موافقة مسبقة من الجهة القطاعية المختصة."},"sourceIds":["S1","S9","S10"],"key":"vocational_license","legalForm":"llc"},{"order":5,"id":"tax_number","title":{"en":"Get a tax number","ar":"الحصول على الرقم الضريبي"},"officeId":"ISTD","requiredDocs":[{"docId":"registration_certificate","condition":"always"},{"docId":"vocational_licence","condition":"always"},{"docId":"lease_contract","condition":"if_rented"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":0,"maxJod":0,"note":{"en":"Free","ar":"مجاناً"},"verified":"yes"},"days":{"value":0,"note":{"en":"Online, same day (up to 24 hours if you apply at the end of the working day); then have the certificate ratified at ISTD in about 5 minutes","ar":"إلكترونياً في نفس اليوم (حتى 24 ساعة إذا قدمت في نهاية الدوام)؛ ثم تصديق الشهادة لدى الدائرة في حوالي 5 دقائق"},"verified":"yes"},"condition":"always","notes":{"en":"Use the tax number on all your invoices.","ar":"استخدم الرقم الضريبي في كل فواتيرك."},"sourceIds":["S10","S12"],"key":"tax_number","legalForm":"llc"},{"order":6,"id":"business_seal","title":{"en":"Make a business stamp","ar":"عمل ختم للمنشأة"},"officeId":"SEAL","requiredDocs":[{"docId":"registration_certificate","condition":"always"},{"docId":"national_id","condition":"always"}],"fee":{"minJod":10,"maxJod":20,"note":{"en":"10-20 JOD at any seal shop","ar":"10 إلى 20 ديناراً في أي محل أختام"},"verified":"yes"},"days":{"value":0,"note":{"en":"Same day","ar":"في نفس اليوم"},"verified":"yes"},"condition":"always","notes":{"en":"You need the stamp to activate your social security account.","ar":"تحتاج الختم لتفعيل حساب الضمان الاجتماعي."},"sourceIds":["S10","S11"],"key":"business_seal","legalForm":"llc"},{"order":7,"id":"social_security","title":{"en":"Register with social security","ar":"التسجيل في الضمان الاجتماعي"},"officeId":"SSC","requiredDocs":[{"docId":"registration_certificate","condition":"always"},{"docId":"vocational_licence","condition":"always"},{"docId":"liaison_officer_form","condition":"always"},{"docId":"national_id","conditio